insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('grisskindlmoakt', 'Grisskindlmoakt', '', '', '', '', 'Christkindlmarkt', '[{"kategorie": "allg", "text": "traditioneller Weihnachtsmarkt, der in der Adventszeit auf dem [[Wiener]] Rathausplatz stattfindet. Er zählt zu den ältesten und bekanntesten Weihnachtsmärkten in Europa und ist eine zentrale Attraktion sowohl für Wiener als auch für Touristen aus aller Welt"}, {"kategorie": "", "text": "Der Wiener Christkindlmarkt hat eine lange Tradition, die bis ins 18. Jahrhundert zurückreicht. Ursprünglich als \"Nikolausmarkt\" bekannt, fand der Markt bereits im Jahr 1296 auf dem Platz [[Am]] Hof statt. Im Laufe der Jahrhunderte entwickelte sich der Markt weiter und verlagerte sich schließlich auf den Rathausplatz, wo er heute jedes Jahr stattfindet"}, {"kategorie": "", "text": "Der Christkindlmarkt erstreckt sich über den gesamten Rathausplatz und bietet eine festlich geschmückte Atmosphäre mit zahlreichen Ständen, die weihnachtliche Waren und kulinarische Spezialitäten anbieten. Die Stände sind traditionell dekoriert und verkaufen eine Vielzahl von handgefertigten Weihnachtsartikeln, darunter Christbaumschmuck, Kunsthandwerk, Kerzen und Krippenfiguren"}, {"kategorie": "", "text": "Neben den Verkaufsständen gibt es auch zahlreiche Essensstände, die typische österreichische Spezialitäten wie gebratene [[Maroni]], [[Punsch]], [[Glühwein]], [[Lebkuchen]] und andere süße Leckereien anbieten. Der Duft von Zimt, Nelken und gebratenen Äpfeln liegt in der Luft und trägt zur besonderen Atmosphäre des Marktes bei"}, {"kategorie": "", "text": "Ein zentrales Element des Christkindlmarkts ist der riesige, festlich beleuchtete Weihnachtsbaum, der auf dem Platz vor dem Wiener Rathaus steht. Der Baum wird jedes Jahr feierlich eröffnet und ist ein beliebter Treffpunkt für Besucher"}]'::jsonb, ''),
  ('fuemfestival', 'Fümfestival', '', '', '', '', 'Filmfestival', '[{"kategorie": "wörtlich, kurz für", "text": "\"Wiener Fimfestival am Rathausplatz\" =  \"jährliche Sommerveranstaltung, die auf dem [[Rathausplatz]] in Wien stattfindet\" (kurz auch \"Film Festival\" genannt)"}, {"kategorie": "", "text": "Es handelt sich um ein Open-Air-Kino-Event, bei dem hochkarätige Film- und Musikproduktionen auf einer großen Leinwand gezeigt werden. Das Festival hat sich seit seiner Gründung zu einem der beliebtesten kulturellen Sommerereignisse in Wien entwickelt"}, {"kategorie": "", "text": "Das Wiener Filmfestival am Rathausplatz wurde erstmals im Jahr 1991 veranstaltet und hat sich seitdem stetig weiterentwickelt. Im Mittelpunkt stehen Musikfilme, Opernaufführungen, Ballette, Konzerte und klassische Musikproduktionen, die auf einer riesigen Leinwand vor dem Wiener Rathaus präsentiert werden. Das Programm wechselt täglich, was es den Besuchern ermöglicht, eine Vielzahl von künstlerischen Darbietungen zu erleben"}, {"kategorie": "", "text": "Neben den Filmvorführungen gibt es ein umfangreiches gastronomisches Angebot. Rund um den Rathausplatz bieten zahlreiche Stände internationale und regionale Spezialitäten an, was das Filmfestival auch zu einem kulinarischen Event macht."}]'::jsonb, ''),
  ('roodhaus', 'Roodhaus', '', '', '', '', 'Rathaus', '[{"kategorie": "wörtlich, kurz für", "text": "\"das Wiener Rathaus\" = \"monumentales, historisches Gebäude im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), das als Sitz des Bürgermeisters und des Wiener Gemeinderats sowie des Wiener Landtags dient"}, {"kategorie": "", "text": "Es wurde zwischen 1872 und 1883 im neugotischen Stil nach den Plänen des Architekten Friedrich von Schmidt errichtet und ist eines der markantesten Bauwerke der [[Wiener]] Ringstraße"}, {"kategorie": "", "text": "Das Wiener Rathaus ist ein herausragendes Beispiel für den neugotischen Baustil, der sich durch seine hochaufragenden Türme, Spitzbögen und filigranen Steinmetzarbeiten auszeichnet. Besonders auffällig ist der zentrale Rathausturm, der eine Höhe von etwa 98 Metern erreicht und von der Statue des à„Rathausmanns“ gekrönt wird, einer symbolischen Figur, die das Gebäude zum Wahrzeichen der Stadt macht"}, {"kategorie": "", "text": "Das Gebäude selbst ist imposant und symmetrisch aufgebaut, mit einer beeindruckenden Fassade, die durch zahlreiche Fenster, Erker und Arkaden gegliedert ist. Die Gesamtlänge des Gebäudes beträgt etwa 152 Meter, und es umfasst mehr als 1.500 Räume, darunter repräsentative Säle wie den Festsaal, der für offizielle Veranstaltungen und Feiern genutzt wird"}, {"kategorie": "", "text": "Der Bau des Rathauses wurde während der großen Stadterweiterung Wiens im späten 19. Jahrhundert initiiert, als die Stadt ihre mittelalterlichen Befestigungsanlagen abriss und die prächtige Ringstraße an ihrer Stelle errichtete. Das Rathaus symbolisiert die politische Macht und die Selbstverwaltung der Stadt Wien"}]'::jsonb, ''),
  ('roodhausplotz', 'Roodhausplotz', '', '', '', '', 'Rathausplatz', '[{"kategorie": "wörtlich, kurz für", "text": "\"Wiener Rathausplatz\" = \"bedeutender öffentlicher Platz im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), der sich direkt vor dem [[Wiener]] Rathaus befindet. Er ist einer der bekanntesten Plätze in Wien und spielt eine zentrale Rolle im städtischen Leben, sowohl als historischer Ort als auch als Veranstaltungsfläche für zahlreiche Großereignisse"}, {"kategorie": "", "text": "Der Rathausplatz wurde zeitgleich mit dem Bau des Wiener Rathauses in den 1870er Jahren angelegt, als Teil der großen städtebaulichen Erweiterungen, die mit der Errichtung der Wiener Ringstraße verbunden waren. Er liegt an der [[Wiener]] Ringstraße, gegenüber dem [[Burgtheater]] und in unmittelbarer Nähe des [[Wiener]] Parlamentsgebäudes und der [[Universität]] Wien. Der Platz ist von wichtigen historischen Gebäuden umgeben und wird von der beeindruckenden Fassade des Wiener Rathauses dominiert. Die Architektur des Rathauses, das im neugotischen Stil errichtet wurde, prägt das Erscheinungsbild des Platzes maßgeblich"}, {"kategorie": "", "text": "Der Platz selbst ist großzügig angelegt und wird von einer Allee aus Bäumen gesäumt, die ihn von der Ringstraße abgrenzt. In der Mitte des Platzes befindet sich eine große Freifläche, die für verschiedene Veranstaltungen genutzt wird, welche das ganze Jahr über dort stattfinden. Zu den prominentesten Ereignissen gehört der [[Wiener]] Christkindlmarkt, der alljährlich in der Adventszeit zahlreiche Besucher anzieht. Der Platz verwandelt sich in dieser Zeit in ein festlich geschmücktes Winterdorf mit zahlreichen Ständen, einem riesigen Weihnachtsbaum und einer Eislaufbahn"}, {"kategorie": "", "text": "Ein weiteres Highlight ist das [[Wiener]] Filmfestival im Sommer, bei dem auf einer großen Leinwand vor dem Rathaus Open-Air-Kino geboten wird. Der Rathausplatz wird außerdem regelmäßig für Konzerte, Festivals, Märkte und politische Kundgebungen genutzt. Auch der [[Wiener]] Eistraum, eine große Eislaufbahn, die in den Wintermonaten auf dem Platz errichtet wird, ist eine beliebte Attraktion."}]'::jsonb, ''),
  ('roodhausmau', 'Roodhausmau', '', '', '', '', 'Rathausmann', '[{"kategorie": "wörtlich", "text": "\"Wiener Rathausmann\" (imposante Statue auf dem Turm des [[Wiener]] Rathauses, die eine symbolische Figur repräsentiert und ein Wahrzeichen der Stadt Wien ist)"}, {"kategorie": "", "text": "\"Wiener Standartenträger\" (Gesamthöhe mit Standarte: 5,4 m; Gesamtgewicht: 1,8 Tonnen, Innengerüst aus Eisen, ansonsten aus Kupfer getrieben, am Tag der Turmgleiche [21. Oktober 1882] auf der Turmspitze angebracht)"}]'::jsonb, ''),
  ('leckn', 'leckn', '', '', '', 'Grundwortschatz Wienerisch', 'lecken', '[{"kategorie": "wörtlich", "text": "\"lecken\" (vom mittelhochdeutschen \"lecken\"=\"benetzen\")"}, {"kategorie": "allg.", "text": "ablecken, anlecken, lutschen, züngeln, [[zuuzln]]"}]'::jsonb, 'Lecko mio!'),
