  ('leiwoerock', 'Leiwörock', '', '', '', '', 'Leiblrock', '[{"kategorie": "wörtlich", "text": "\"Leibrock\" (vom mittelhochdeutschen \"līp\"=\"Leib\")"}, {"kategorie": "", "text": "ärmelloses Damenkleid bzw. Bluse und Rock in einem (meist durchgehend knöpfbar)"}, {"kategorie": "", "text": "Gehrock, Herrengehrock (eine doppelreihige Jacke mit knielangem, angesetztem Schoß aus meist dunklem Tuch)"}]'::jsonb, ''),
