  ('leachal', 'Leachal', '', '', '', '', 'Lercherl', '[{"kategorie": "wörtlich", "text": "\"kleine Lerche\" (Verkleinerungsform von \"Lerche\"=Singvogel mit besonders melodiösem Gesang)"}, {"kategorie": "", "text": "Kunstpfeifer, \"Vogelimitator\" (einer der berühmtesten war der Wiener Leopold Gottwald [1873-1930], Spitzname \"s''Lercherl\")"}, {"kategorie": "fig.", "text": "sanftmütiger Mensch (der niemandem etwas zuleide tun kann), [[guter]] Latsch, [[Lamperl]]"}, {"kategorie": "Gaunersprache", "text": "Hinweisgeber, \"Whistleblower\", [[Ezzesgeber]], [[Wamserl]], [[Vernaderer]] (jemand, der \"singt wie eine Lerche\")"}, {"kategorie": "fig., allg.", "text": "Bagatelle, Petitesse, harmlose Kleinigkeit"}, {"kategorie": "", "text": "Prostituierte, [[Drossel]], [[Schnepfen]], [[Aspaltschwalbe]]"}]'::jsonb, 'Des is kaa Leachal!'),
