  ('haumpaemau', 'Haumpämau', '', '', '', '', 'Hampelmann', '[{"kategorie": "wörtlich", "text": "\"Spielfigur, deren Arme und Beine mittels einer Schnur bewegt werden können\""}, {"kategorie": "fig.", "text": "willensschwacher Mann, Weichling, Marionette, [[Lötfeigen]]"}]'::jsonb, ''),
