  ('haundzaam', 'haundzaam', '', '', '', '', 'handzahm', '[{"kategorie": "wörtlich", "text": "\"zahm genug, um sich mit der Hand berühren zu lassen\" (vom althochdeutschen \"hant\"=\"Hand\" bzw. vom mittelhochdeutschen \"tām\"=\"zahm\""}, {"kategorie": "", "text": "äußerst zahm, zutraulich, gutmütig (auch von Personen)"}]'::jsonb, ''),
  ('levkoje', 'Levkoje', '', '', '', '', 'Levkoje', '[{"kategorie": "wörtlich", "text": "\"Levkoje\" (botanischer Name: \"Matthiola incana\" = Blumenpflanze [Kreuzblütler mit duftenen Blüten] von den Küsten des zentralen Mittelmeerraumes, abgeleitet vom griechischen \"leukoion\"=\"Weißveilchen\")"}, {"kategorie": "", "text": "Veilchen, [[Veigerl]]"}, {"kategorie": "jiddisch, scherzhaft für", "text": "weibliches Geschlechtsteil, Scheide, [[Fut]], [[Muff]], [[Buschen]]"}]'::jsonb, ''),
  ('liachdbraadl', 'Liachdbraadl', '', '', '', '', 'Lichtbratl', '[{"kategorie": "wörtlich", "text": "\"Lichtbraten\" (=\"Braten für die Handwerker zu Beginn der Kunstlichtzeit\")"}, {"kategorie": "", "text": "Herbstbraten, \"Kunstlichtbraten\" (meist Truthahnbraten, den die Handwerker ihren Gesellen zu Beginn der Herbstzeit als Anerkennung dafür spendierten, dass sie fortan [in der dunklen Jahreszeit] mit Kunstlicht arbeiten mussten)"}]'::jsonb, ''),
  ('liachdln', 'Liachdln', '', '', '', '', 'Lichteln', '[{"kategorie": "wörtlich", "text": "\"die lichten Röhren\" (vom mittelhochdeutschen \"lieht\"=\"licht\" [Adjektiv, \"die inne Ausdehnung von Hohlräumen betreffend])"}, {"kategorie": "Fleischhauerjargon", "text": "\"Herzröhre und Aorta\", \"die als weiße Ringe sichtbaren Adern im Fleisch\"  (wie z.B. im [[Bruckfleisch]] oder [[Beuschel]], beides klassische Gerichte der Wiener Küche), siehe auich [[Liachdl]]"}]'::jsonb, ''),
  ('liachdn', 'Liachdn', '', '', '', '', 'Lichten', '[{"kategorie": "wörtlich", "text": "\"Helligkeit\" (vom mittelhochdeutschen \"lieht\"=\"hell\")"}, {"kategorie": "", "text": "Licht, Leuchtkraft, Helle"}]'::jsonb, ''),
