  ('mettn', 'Mettn', '', '', '', '', 'Metten', '[{"kategorie": "wörtlich", "text": "\"Mette\" (vom mittelhochdeutschen \"metten\"=\"Mette\")"}, {"kategorie": "", "text": "Christmette, Karmette, Ostermette (frühmorgendlicher, spätabendlicher oder mitternächtlicher Gottesdienst vor einem hohen kirchlichen Feiertag)"}, {"kategorie": "fig., scherzhaft für", "text": "rauschendes Fest, Krawallparty, ausgelassenes Gelage"}]'::jsonb, ''),
  ('gruendazeithaus', 'Gründazeithaus', '', '', '', '', 'Gründerzeithaus', '[{"kategorie": "allg.", "text": "\"Wohn- oder Geschäftshaus, das während der sogenannten [[Gründerzeit]] errichtet wurde, einer Epoche, die etwa zwischen 1840 und dem Beginn des Ersten Weltkriegs 1914 datiert wird\""}, {"kategorie": "", "text": "Diese Gebäude sind charakteristisch für die rasante Urbanisierung und das städtische Wachstum in Mitteleuropa, insbesondere in Städten des Deutschen Kaiserreichs und der [[Donaumonarchie]] (Österreich-Ungarn)"}, {"kategorie": "", "text": "Gründerzeithäuser sind bekannt für ihre prächtigen, oft opulenten Fassaden. Diese sind meist im Stil des [[Historismus]] gehalten, einer Epoche, die verschiedene historische Baustile wie Neorenaissance, Neobarock, Neogotik oder Neoklassizismus wiederaufgriff und kombinierte"}, {"kategorie": "", "text": "Die Fassaden sind häufig reich verziert mit Stuckelementen, Ornamenten, Säulen, Gesimsen, Erkern und Balkonen. Diese dekorativen Elemente sollten den Wohlstand und die Repräsentativität der Bewohner oder Eigentümer zum Ausdruck bringen"}, {"kategorie": "", "text": "Innen waren die Wohnungen in Gründerzeithäusern oft großzügig geschnitten, mit hohen Decken und großen Fenstern, was eine helle und luftige Atmosphäre schuf"}, {"kategorie": "", "text": "Die Erdgeschosse wurden häufig für Geschäfte oder andere gewerbliche Zwecke genutzt, während die oberen Stockwerke Wohnraum boten. Die wertvollsten Wohnungen befanden sich oft im ersten Obergeschoss, der sogenannten „Beletage“, die wegen der einfachen Erreichbarkeit und der besseren Aussicht bevorzugt wurde"}]'::jsonb, ''),
