  ('niachdln', 'niachdln', '', '', '', '', 'nüachteln', '[{"kategorie": "wörtlich", "text": "\"einen unangenehmen Geruch verbreiten\" (eigentlich [[miachteln]], vom mittelhochdeutschen \"müechteln\"=\"müffeln\")"}, {"kategorie": "", "text": "miefen, muffeln, leicht stinken, [[muffeln]] (modrig, schimmelig oder faulig riechen)"}]'::jsonb, 'Do niachdlts!'),
