  ('muatadella', 'Muatadella!', '', '', '', '', 'Mortadella', '[{"kategorie": "wörtlich", "text": "\"Mortadella\" (vom italienischen \"mortadella\" = italienische Wurst aus Schweine- und Kalbfleisch, oft mit Pistazien, Oliven oder Peperoni verfeinert)"}, {"kategorie": "aufgrund des Gleichklangs, Verballhornung von", "text": "\"Mutter Gottes!\" (Ausdruck des Erstaunens oder Entsetzens bzw. der Überraschung oder Bestürzung)"}, {"kategorie": "", "text": "Wahnsinn!  Wow!  Donnerwetter!  Das ist ja zum Niederknien! Himmel noch mal!  [[Marantana]]!  [[Bist]] du deppert! [[Bist]] du Moped!"}]'::jsonb, ''),
