  ('muckn', 'Muckn', '', '', '', '', 'Mucken', '[{"kategorie": "wörtlich", "text": "\"Mucke\" (vom althochdeutschen \"mucka\"=\"Mucke\")"}, {"kategorie": "allg.", "text": "kleines Stechinsekt, Stechmücke, Moskito"}, {"kategorie": "fig., von Personen", "text": "Eigenheit, Eigenart, Marotte, \"Macke\""}, {"kategorie": "von Dingen", "text": "Fehler, Mangel, kleiner Defekt"}]'::jsonb, 'Des woa, wiara no mit d''Muckn gfloong is!'),
